val pcm = File(directory, "qa08-native-capture-$cohort.pcm")
val metadata = File(directory, "qa08-native-capture-$cohort.json")
require(pcm.canonicalFile.parentFile == directory && metadata.canonicalFile.parentFile == directory)
require(!pcm.exists() && !metadata.exists())
val bytes = ByteBuffer.allocate(samples.size * 2).order(ByteOrder.LITTLE_ENDIAN).apply {
  samples.forEach { putShort((it * 32768f).toInt().coerceIn(-32768, 32767).toShort()) }
}.array()
try {
  Files.newOutputStream(pcm.toPath(), StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE).use { it.write(bytes) }

  val result = JSONObject().put("kind", "DATAQA_EXPLICIT_EMULATOR_SYNTHETIC_CAPTURE")
    .put("cohort", cohort).put("fixtureId", fixture).put("sourceWavSha256", pin.second)
    .put("createdAtUtc", now.toString()).put("vocabulary", vocabulary.name)
    .put("sampleRate", SpeechInputPolicy.SAMPLE_RATE).put("frames", samples.size)
    .put("pcmFile", pcm.name).put("bytes", bytes.size).put("sha256", digest(bytes))
    .put("nonzeroFrames", samples.count { it != 0f })
    .put("rms", sqrt(samples.sumOf { it.toDouble() * it } / maxOf(1, samples.size)))
    .put("peak", samples.maxOfOrNull { abs(it) } ?: 0f)
    .put("physicalDeviceValidation", "NOT_RUN").put("rootMustFetchPrivatelyAndRemoveExactFiles", true)
  Files.newOutputStream(metadata.toPath(), StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE).use {
    it.write(result.toString(2).toByteArray(Charsets.UTF_8))
  }
} finally { bytes.fill(0) }

  } catch (failure: Exception) {
    // Diagnostics never change normal recording, recognition or manual fallback behavior.
    Log.d("CapstoneStt", "synthetic diagnostic not exported: ${failure.javaClass.simpleName}")
  }
}

private fun digest(bytes: ByteArray): String = MessageDigest.getInstance("SHA-256").digest(bytes)
  .joinToString("") { "%02x".format(it.toInt() and 255) }
